{"command":"mkdir -p src
cat > src/direnv_clone.py <<'PY'
#!/usr/bin/env python3
import base64, hashlib, json, os, re, shutil, stat, subprocess, sys, tempfile, time, zlib
from pathlib import Path
from urllib.request import urlopen, Request

VERSION = "2.37.1"
ERROR_RED = "\033[31m"
RESET = "\033[0m"
INTERNAL_IGNORES = {"PWD", "OLDPWD", "SHLVL", "_", "DIRENV_IN_ENVRC"}
CONTROL_VARS = {"DIRENV_DIR", "DIRENV_FILE", "DIRENV_DIFF", "DIRENV_WATCHES"}

# ---------------- utilities ----------------
def self_path():
    return os.path.abspath(sys.argv[0])

def home():
    return os.environ.get("HOME", str(Path.home()))

def xdg_config_home():
    v = os.environ.get("XDG_CONFIG_HOME")
    return v if v else os.path.join(home(), ".config")

def xdg_data_home():
    v = os.environ.get("XDG_DATA_HOME")
    return v if v else os.path.join(home(), ".local", "share")

def xdg_cache_home():
    v = os.environ.get("XDG_CACHE_HOME")
    return v if v else os.path.join(home(), ".cache")

def config_dir():
    return os.environ.get("DIRENV_CONFIG") or os.path.join(xdg_config_home(), "direnv")

def data_dir():
    return os.path.join(xdg_data_home(), "direnv")

def cache_dir():
    return os.path.join(xdg_cache_home(), "direnv")

def eprint(s=""):
    sys.stderr.write(str(s))
    if not str(s).endswith("\n"):
        sys.stderr.write("\n")

def load_config():
    cfg = {
        "bash_path": shutil.which("bash") or "/usr/bin/bash",
        "disable_stdin": False,
        "load_dotenv": False,
        "strict_env": False,
        "warn_timeout": os.environ.get("DIRENV_WARN_TIMEOUT", "5s"),
        "hide_env_diff": False,
        "log_format": None,
        "log_filter": None,
        "whitelist_prefix": [],
        "whitelist_exact": [],
    }
    path = os.path.join(config_dir(), "direnv.toml")
    if not os.path.exists(path):
        old = os.path.join(config_dir(), "config.toml")
        if os.path.exists(old): path = old
    section = None
    if os.path.exists(path):
        try:
            for raw in open(path, encoding="utf-8"):
                line = raw.strip()
                if not line or line.startswith("#"): continue
                m = re.match(r"\[([^]]+)\]", line)
                if m:
                    section = m.group(1).strip(); continue
                if "=" not in line: continue
                k, v = line.split("=", 1); k=k.strip(); v=v.strip()
                # strip inline comment outside of strings (minimal)
                if v.startswith('"') and v.endswith('"'):
                    val = bytes(v[1:-1], "utf-8").decode("unicode_escape")
                elif v.lower() in ("true","false"):
                    val = v.lower()=="true"
                elif v.startswith("["):
                    val = re.findall(r'"((?:[^"\\]|\\.)*)"', v)
                    val = [bytes(x,"utf-8").decode("unicode_escape") for x in val]
                else:
                    val = v.strip('"')
                if section == "global":
                    if k in cfg: cfg[k] = val
                elif section == "whitelist":
                    if k == "prefix" and isinstance(val, list): cfg["whitelist_prefix"] = [expand_user(x) for x in val]
                    if k == "exact" and isinstance(val, list): cfg["whitelist_exact"] = [normalize_exact(x) for x in val]
        except Exception:
            pass
    return cfg

def log_enabled(status=True):
    cfg = load_config()
    fmt = os.environ.get("DIRENV_LOG_FORMAT")
    if fmt is None: fmt = cfg.get("log_format")
    return fmt != "-"

def log_status(msg):
    if log_enabled(True):
        sys.stderr.write(f"{RESET}direnv: {msg}\n")

def log_error(msg):
    sys.stderr.write(f"{ERROR_RED}direnv: error {msg}{RESET}\n")

def expand_user(p):
    return os.path.abspath(os.path.expanduser(os.path.expandvars(p)))

def normalize_exact(p):
    p = expand_user(p)
    if os.path.isdir(p):
        p = os.path.join(p, ".envrc")
    return os.path.abspath(p)

def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def rc_hash(path):
    b = open(path, "rb").read()
    return sha256_hex(os.path.abspath(path).encode() + b"\n" + b)

def marker_path(kind, path):
    return os.path.join(data_dir(), kind, rc_hash(path))

def write_marker(kind, path):
    p = marker_path(kind, path)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as f:
        f.write(os.path.abspath(path).encode() + b"\n")
    return p

def is_whitelisted(path, cfg):
    ap = os.path.abspath(path)
    for p in cfg.get("whitelist_prefix", []):
        if ap.startswith(p): return True
    for p in cfg.get("whitelist_exact", []):
        if ap == p: return True
    return False

def auth_status(path, cfg=None):
    cfg = cfg or load_config()
    if is_whitelisted(path, cfg): return "allowed"
    try:
        if os.path.exists(marker_path("deny", path)): return "denied"
        if os.path.exists(marker_path("allow", path)): return "allowed"
    except FileNotFoundError:
        pass
    return "blocked"

def find_rc(start=None, cfg=None):
    cfg = cfg or load_config()
    d = os.path.abspath(start or os.getcwd())
    if os.path.isfile(d):
        d = os.path.dirname(d)
    while True:
        envrc = os.path.join(d, ".envrc")
        if os.path.exists(envrc): return os.path.abspath(envrc)
        if cfg.get("load_dotenv"):
            env = os.path.join(d, ".env")
            if os.path.exists(env): return os.path.abspath(env)
        nd = os.path.dirname(d)
        if nd == d: return None
        d = nd

def resolve_rc_arg(arg, for_edit=False, cfg=None):
    cfg = cfg or load_config()
    if not arg:
        p = find_rc(os.getcwd(), cfg)
        return p
    p = os.path.abspath(os.path.expanduser(arg))
    if os.path.isdir(p):
        e = os.path.join(p, ".envrc")
        if os.path.exists(e) or not cfg.get("load_dotenv"):
            return os.path.abspath(e)
        de = os.path.join(p, ".env")
        return os.path.abspath(de)
    # If direct .env is requested but dotenv loading disabled, original behaves as if .envrc is wanted.
    if os.path.basename(p) == ".env" and not cfg.get("load_dotenv"):
        return os.path.join(os.path.dirname(p), ".envrc")
    return p

# ---------------- state encoding ----------------
def b64z(obj):
    raw = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode()
    return base64.urlsafe_b64encode(zlib.compress(raw)).decode()

def unb64z(s):
    try:
        return json.loads(zlib.decompress(base64.urlsafe_b64decode(s.encode())).decode())
    except Exception:
        return None

def parse_state(env=None):
    env = env or os.environ
    d = unb64z(env.get("DIRENV_DIFF", ""))
    if isinstance(d, dict) and d.get("py_direnv") == 1:
        return d
    return None

def restored_base_env(cur=None):
    cur = dict(cur or os.environ)
    st = parse_state(cur)
    if st:
        prev = st.get("previous", {})
        for k, v in prev.items():
            if v is None: cur.pop(k, None)
            else: cur[k] = v
        for k in CONTROL_VARS: cur.pop(k, None)
    return cur

def env_changes(current, final):
    # Return mapping key -> value or None to transform current into final.
    changes = {}
    keys = (set(current) | set(final)) - INTERNAL_IGNORES
    for k in sorted(keys):
        if k.startswith("BASH_FUNC_"): continue
        cv = current.get(k); fv = final.get(k)
        if fv is None and k in current:
            changes[k] = None
        elif fv is not None and cv != fv:
            changes[k] = fv
    return changes

# ---------------- shell escaping / rendering ----------------
def bash_quote(v):
    if v is None: return "''"
    s = str(v)
    out = "$'"
    for ch in s:
        o = ord(ch)
        if ch == "\\": out += "\\\\"
        elif ch == "'": out += "\\'"
        elif ch == "\n": out += "\\n"
        elif ch == "\r": out += "\\r"
        elif ch == "\t": out += "\\t"
        elif o < 32 or o == 127: out += "\\x%02x" % o
        else: out += ch
    return out + "'"

def sq(v):
    return "'" + str(v).replace("'", "'\\''") + "'"

def psq(v):
    return "'" + str(v).replace("'", "''") + "'"

def tcsh_quote(v):
    return str(v).replace(" ", "\\ ").replace('"', '\\"')

def render(shell, changes):
    if shell in ("bash", "zsh"):
        parts=[]
        for k,v in changes.items():
            if v is None: parts.append(f"unset {k};")
            else: parts.append(f"export {k}={bash_quote(v)};")
        return "".join(parts)
    if shell == "fish":
        parts=[]
        for k,v in changes.items():
            if v is None: parts.append(f"set -e -g {sq(k)};")
            else: parts.append(f"set -x -g {sq(k)} {sq(v)};")
        return "".join(parts)
    if shell == "tcsh":
        parts=[]
        for k,v in changes.items():
            if v is None: parts.append(f"unsetenv {k} ;")
            else: parts.append(f"setenv {k} {tcsh_quote(v)} ;")
        return "".join(parts)
    if shell in ("json",):
        return json.dumps(changes, indent=2, sort_keys=True)
    if shell in ("elvish", "murex"):
        return json.dumps(changes, separators=(",", ":"), sort_keys=True)
    if shell == "pwsh":
        parts=[]
        for k,v in changes.items():
            if v is None: parts.append(f"Remove-Item -LiteralPath 'env:/{k}';")
            else: parts.append(f"${{env:{k}}}={psq(v)};")
        return "".join(parts)
    if shell == "vim":
        lines=[]
        for k,v in changes.items():
            if v is None: lines.append(f"call setenv('{k}',v:null)")
            else: lines.append(f"call setenv('{k}',{sq(v)})")
        return "\n".join(lines)
    if shell == "systemd":
        lines=[]
        for k,v in changes.items():
            if v is not None: lines.append(f"{k}={v}")
        return "\n".join(lines)
    if shell == "gha":
        lines=[]
        for k,v in changes.items():
            if v is None: continue
            delim = "ghadelimiter_" + hashlib.md5((k+str(v)).encode()).hexdigest()
            lines += [f"{k}<<{delim}", str(v), delim]
        return "\n".join(lines)
    if shell == "gzenv":
        return b64z({k:v for k,v in changes.items() if v is not None})
    raise ValueError(shell)

def check_shell(shell):
    shells = {"bash","zsh","fish","tcsh","elvish","pwsh","murex","json","vim","gha","gzenv","systemd"}
    if shell not in shells:
        log_error(f"unknown target shell '{shell}'")
        return False
    return True

# ---------------- stdlib / evaluation ----------------
def stdlib_text():
    sp = self_path().replace('"', '\\"')
    return f'''#!/usr/bin/env bash
#
# These are the commands available in an .envrc context
#
shopt -s nullglob
shopt -s extglob

direnv="{sp}"
direnv_config_dir="${{DIRENV_CONFIG:-${{XDG_CONFIG_HOME:-$HOME/.config}}/direnv}}"
export DIRENV_IN_ENVRC=1

log_status() {{ "$direnv" log --status "$*"; }}
log_error() {{ "$direnv" log --error "$*"; }}
has() {{ type "$1" >/dev/null 2>&1; }}
expand_path() {{ local p="$1"; local r="${{2:-$PWD}}"; case "$p" in /*) printf '%s\n' "$p";; ~*) eval "printf '%s\\n' $p";; *) (cd "$r" 2>/dev/null && cd "$(dirname "$p")" 2>/dev/null && printf '%s/%s\n' "$PWD" "$(basename "$p")") || return 1;; esac; }}
user_rel_path() {{ case "$1" in "$HOME"/*) echo "~/${{1#$HOME/}}";; "$HOME") echo '~';; *) echo "$1";; esac; }}
find_up() {{ local f="${{1:-.envrc}}" d="$PWD"; while :; do [ -e "$d/$f" ] && {{ echo "$d/$f"; return 0; }}; [ "$d" = / ] && return 1; d="$(dirname "$d")"; done; }}
dotenv() {{ local f="${{1:-.env}}"; eval "$("$direnv" dotenv bash "$f")"; }}
dotenv_if_exists() {{ local f="${{1:-.env}}"; [ -e "$f" ] && dotenv "$f" || true; }}
source_env() {{ local f="$1"; [ -d "$f" ] && f="$f/.envrc"; source "$f"; }}
source_env_if_exists() {{ [ -e "$1" ] && source "$1" || true; }}
source_up() {{ local f="${{1:-.envrc}}" p; p="$(find_up "$f")" || return 1; source "$p"; }}
source_up_if_exists() {{ source_up "${{1:-.envrc}}" || true; }}
env_vars_required() {{ local e=0; for v in "$@"; do [ -n "${{!v:-}}" ] || {{ log_error "$v is missing"; e=1; }}; done; return $e; }}
path_add() {{ local var="$1" p; p="$(expand_path "$2")" || return; eval "export $var=\"$p${{!var:+:${{!var}}}}\""; }}
PATH_add() {{ path_add PATH "$1"; }}
MANPATH_add() {{ path_add MANPATH "$1"; }}
PATH_rm() {{ local new= part pat remove; IFS=: read -ra __parts <<< "$PATH"; for part in "${{__parts[@]}}"; do remove=0; for pat in "$@"; do [[ "$part" == $pat ]] && remove=1; done; [ $remove -eq 0 ] && new="${{new:+$new:}}$part"; done; export PATH="$new"; }}
load_prefix() {{ local p; p="$(expand_path "$1")" || return; PATH_add "$p/bin"; path_add CPATH "$p/include"; path_add LD_LIBRARY_PATH "$p/lib"; path_add LIBRARY_PATH "$p/lib"; MANPATH_add "$p/share/man"; path_add PKG_CONFIG_PATH "$p/lib/pkgconfig"; }}
watch_file() {{ :; }}
watch_dir() {{ :; }}
require_allowed() {{ :; }}
direnv_version() {{ "$direnv" version "$1"; }}
strict_env() {{ if [ $# -gt 0 ]; then (set -euo pipefail; "$@"); else set -euo pipefail; fi; }}
unstrict_env() {{ set +e +u +o pipefail; }}
direnv_layout_dir() {{ echo "${{direnv_layout_dir:-$PWD/.direnv}}"; }}
layout() {{ case "$1" in python|python3) local py="${{2:-python3}}"; local d="$(direnv_layout_dir)/python"; [ -d "$d" ] || "$py" -m venv "$d" 2>/dev/null || true; export VIRTUAL_ENV="$d"; PATH_add "$d/bin";; node) PATH_add node_modules/.bin;; *) :;; esac; }}
use() {{ :; }}
rvm() {{ :; }}
fetchurl() {{ "$direnv" fetchurl "$@"; }}
source_url() {{ local p; p="$(fetchurl "$1" "$2")" || return; source "$p"; }}
direnv_apply_dump() {{ "$direnv" apply_dump "$1"; }}
direnv_load() {{ eval "$("$@")"; }}
semver_search() {{ find "$1" -maxdepth 1 -type d -name "$2$3*" 2>/dev/null | sort -V | tail -n1; }}
on_git_branch() {{ local b; b="$(git branch --show-current 2>/dev/null)" || return 1; [ $# -eq 0 ] && echo "$b" || [ "$b" = "$1" ]; }}
'''

def run_bash_capture(rc_path, base_env, cfg):
    bash = cfg.get("bash_path") or shutil.which("bash") or "/usr/bin/bash"
    if not os.path.exists(bash): bash = shutil.which("bash") or "bash"
    rc_dir = os.path.dirname(rc_path)
    rc_base = os.path.basename(rc_path)
    env = dict(base_env)
    env["DIRENV_IN_ENVRC"] = "1"
    env["DIRENV_CONFIG"] = config_dir()
    script_file = tempfile.NamedTemporaryFile("w", delete=False)
    dump_file = tempfile.NamedTemporaryFile(delete=False); dump_file.close()
    try:
        script_file.write(stdlib_text())
        # user extensions
        drc = os.path.join(config_dir(), "direnvrc")
        script_file.write(f'\n[ -f {bash_quote(drc)} ] && source {bash_quote(drc)}\n')
        libdir = os.path.join(config_dir(), "lib")
        script_file.write(f'for f in {bash_quote(libdir)}/*.sh; do [ -e "$f" ] && source "$f"; done\n')
        script_file.write(f'cd {bash_quote(rc_dir)} || exit 1\n')
        if cfg.get("strict_env"):
            script_file.write('set -euo pipefail\n')
        if rc_base == ".env":
            # dotenv is loaded with auto-export in a bash-compatible way.
            script_file.write('set -a\n')
        script_file.write(f'source ./{bash_quote(rc_base)[2:-1] if bash_quote(rc_base).startswith("$'") else rc_base}\n')
        if rc_base == ".env": script_file.write('set +a\n')
        script_file.write(f'env -0 > {bash_quote(dump_file.name)}\n')
        script_file.close()
        stdin = subprocess.DEVNULL if cfg.get("disable_stdin") else None
        p = subprocess.run([bash, script_file.name], env=env, cwd=rc_dir, stdin=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if p.stdout:
            # direnv sends envrc stdout to stderr
            try: sys.stderr.buffer.write(p.stdout)
            except Exception: sys.stderr.write(p.stdout.decode(errors="replace"))
        if p.stderr:
            try: sys.stderr.buffer.write(p.stderr)
            except Exception: sys.stderr.write(p.stderr.decode(errors="replace"))
        if p.returncode != 0:
            return None, p.returncode
        data = open(dump_file.name, "rb").read()
        out = {}
        for item in data.split(b"\0"):
            if not item or b"=" not in item: continue
            k,v = item.split(b"=",1)
            try:
                ks=k.decode(); vs=v.decode()
            except UnicodeDecodeError:
                ks=k.decode(errors="replace"); vs=v.decode(errors="replace")
            if ks in INTERNAL_IGNORES or ks.startswith("BASH_FUNC_"): continue
            out[ks]=vs
        return out, 0
    finally:
        try: os.unlink(script_file.name)
        except Exception: pass
        try: os.unlink(dump_file.name)
        except Exception: pass

def rc_watch_value(rc_path):
    try:
        st = os.stat(rc_path)
        obj = {"py_watches":1,"files":[[os.path.abspath(rc_path), int(st.st_mtime), st.st_size]]}
    except FileNotFoundError:
        obj = {"py_watches":1,"files":[]}
    return b64z(obj)

def load_rc_env(rc_path, base_env, cfg, for_exec=False):
    if os.path.basename(rc_path) == ".envrc":
        log_status(f"loading {rc_path}")
    new_env, code = run_bash_capture(rc_path, base_env, cfg)
    if code != 0 or new_env is None:
        return None, code or 1
    return new_env, 0

def summarize_diff(changes):
    plus=[]; minus=[]; tilde=[]
    for k,v in changes.items():
        if k in CONTROL_VARS: continue
        if v is None: minus.append("-"+k)
        elif k in os.environ: tilde.append("~"+k)
        else: plus.append("+"+k)
    bits = sorted(plus)+sorted(minus)+sorted(tilde)
    if bits:
        log_status("export " + " ".join(bits))

