def cmd_version(args):
    if not args:
        print(VERSION); return 0
    want = args[0]
    def parse(v):
        if v.startswith("v"): v=v[1:]
        m=re.match(r"^(\d+)\.(\d+)(?:\.(\d+))?(?:[-+][A-Za-z0-9.-]+)?$", v)
        if not m: return None
        return tuple(int(x or 0) for x in m.groups())
    w=parse(want); cur=parse(VERSION)
    if w is None:
        log_error(f"v{want} is not a valid semver version"); return 1
    if cur < w:
        log_error(f"current version v{VERSION} is older than the desired version v{want}"); return 1
    return 0

