def cmd_allow(args, deny=False):
    cfg = load_config()
    p = resolve_rc_arg(args[0] if args else None, cfg=cfg)
    if not p or not os.path.exists(p):
        log_error(".envrc file not found"); return 1
    write_marker("deny" if deny else "allow", p)
    return 0

def cmd_edit(args):
    cfg = load_config()
    p = resolve_rc_arg(args[0] if args else None, for_edit=True, cfg=cfg)
    if not p:
        log_error(".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory"); return 1
    editor = os.environ.get("EDITOR") or os.environ.get("VISUAL") or "vi"
    before = os.path.getmtime(p) if os.path.exists(p) else None
    os.makedirs(os.path.dirname(p), exist_ok=True)
    r = subprocess.run([editor, p]).returncode
    if r != 0:
        log_error(f"exit status {r}"); return r
    after = os.path.getmtime(p) if os.path.exists(p) else None
    if os.path.exists(p) and (before != after or before is None):
        write_marker("allow", p)
    return 0

def prepare_export(shell):
    cfg = load_config()
    if not check_shell(shell): return 1
    cur = dict(os.environ)
    base = restored_base_env(cur)
    rc = find_rc(os.getcwd(), cfg)
    st = parse_state(cur)
    # no rc: unload previous if it was our state
    if not rc:
        if st:
            final = dict(base)
            changes = env_changes(cur, final)
            if changes:
                log_status("unloading")
                out = render(shell, changes)
                if out: sys.stdout.write(out)
            return 0
        return 0
    rh = rc_hash(rc)
    if st and st.get("rc") == rc and st.get("hash") == rh:
        return 0
    auth = auth_status(rc, cfg)
    if auth == "denied":
        # Deliberately ignored; update only bookkeeping minimally.
        final = dict(base)
        return_output(shell, cur, final, rc, rh, loaded=False, summarize=False)
        return 0
    if auth != "allowed":
        final = dict(base)
        # include bookkeeping, then error, as direnv does for blocked files.
        changes = build_changes(cur, final, rc, rh, loaded=False)
        out = render(shell, changes)
        if out: sys.stdout.write(out)
        log_error(f"{rc} is blocked. Run `direnv allow` to approve its content")
        return 1
    new, code = load_rc_env(rc, base, cfg)
    if code != 0:
        return code
    return_output(shell, cur, new, rc, rh, loaded=True, summarize=not cfg.get("hide_env_diff"))
    return 0

def build_changes(cur, final_noctrl, rc, rh, loaded=True):
    base = restored_base_env(cur)
    final = dict(final_noctrl)
    # compute previous values for vars that differ between restored base and final (managed vars)
    managed_prev = {}
    for k in (set(base)|set(final)) - INTERNAL_IGNORES - CONTROL_VARS:
        if base.get(k) != final.get(k):
            managed_prev[k] = base.get(k) if k in base else None
    state = {"py_direnv":1,"rc":rc if loaded else None,"hash":rh if loaded else None,"previous":managed_prev,"loaded":loaded}
    final["DIRENV_DIR"] = "-" + os.path.dirname(rc)
    final["DIRENV_FILE"] = rc
    final["DIRENV_WATCHES"] = rc_watch_value(rc)
    final["DIRENV_DIFF"] = b64z(state)
    return env_changes(cur, final)

def return_output(shell, cur, final_noctrl, rc, rh, loaded=True, summarize=True):
    changes = build_changes(cur, final_noctrl, rc, rh, loaded)
    if summarize: summarize_diff(changes)
    out = render(shell, changes)
    if out: sys.stdout.write(out)

def cmd_exec(args):
    if len(args) == 0:
        log_error("missing DIR and COMMAND arguments"); return 1
    if len(args) == 1:
        log_error("missing COMMAND argument"); return 1
    d=args[0]
    if not os.path.exists(d):
        log_error(f"stat {d}: no such file or directory"); return 1
    cfg=load_config(); rc=find_rc(d, cfg)
    env=restored_base_env(dict(os.environ))
    if rc:
        auth=auth_status(rc,cfg)
        if auth != "allowed":
            if auth == "blocked": log_error(f"{rc} is blocked. Run `direnv allow` to approve its content")
            return 1
        new,code=load_rc_env(rc, env, cfg, for_exec=True)
        if code != 0: return code
        env=new
        for k in CONTROL_VARS: env.pop(k, None)
    try:
        p=subprocess.run(args[1:], env=env)
        return p.returncode
    except FileNotFoundError:
        log_error(f"exec: {args[1]}: executable file not found in $PATH")
        return 1

def cmd_status(args):
    cfg=load_config(); rc=find_rc(os.getcwd(), cfg); st=parse_state(os.environ)
    if args and args[0] == "--json":
        obj={"config":{"ConfigDir":config_dir(),"SelfPath":self_path()},"state":{"foundRC":None,"loadedRC":None}}
        if rc: obj["state"]["foundRC"]={"path":rc,"allowed":auth_status(rc,cfg)=="allowed"}
        if st and st.get("rc"): obj["state"]["loadedRC"]={"path":st.get("rc"),"allowed":True}
        print(json.dumps(obj, indent=2))
        return 0
    print(f"direnv exec path {self_path()}")
    print(f"DIRENV_CONFIG {config_dir()}")
    print(f"bash_path {cfg.get('bash_path')}")
    print(f"disable_stdin {str(cfg.get('disable_stdin')).lower()}")
    print(f"warn_timeout {cfg.get('warn_timeout')}")
    print("whitelist.prefix [" + " ".join(cfg.get("whitelist_prefix",[])) + "]")
    print("whitelist.exact map[]" if not cfg.get("whitelist_exact") else "whitelist.exact " + str(cfg.get("whitelist_exact")))
    if st and st.get("rc"):
        print(f"Loaded RC path {st.get('rc')}")
    else:
        print("No .envrc or .env loaded")
    if rc:
        print(f"Found RC path {rc}")
        try:
            mt=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(os.stat(rc).st_mtime))
            print(f"Found watch: \"{os.path.basename(rc)}\" - {mt}")
        except Exception: pass
        print("Found RC allowed " + ("0" if auth_status(rc,cfg)=="allowed" else "-1"))
        print(f"Found RC allowPath {marker_path('allow', rc)}")
    else:
        print("No .envrc or .env found")
    return 0

def cmd_prune():
    root=data_dir(); removed=0
    ad=os.path.join(root,"allow")
    if not os.path.isdir(ad):
        log_error(f"open {ad}: no such file or directory"); return 1
    for kind in ("allow","deny"):
        d=os.path.join(root,kind)
        if not os.path.isdir(d): continue
        for fn in os.listdir(d):
            fp=os.path.join(d,fn)
            try:
                p=open(fp,"rb").read().decode().strip()
                if not os.path.exists(p) or rc_hash(p) != fn:
                    os.unlink(fp); removed += 1
            except Exception:
                try: os.unlink(fp); removed += 1
                except Exception: pass
    if removed: log_status(f"pruned {removed} files")
    return 0

def cmd_reload():
    rc=find_rc(os.getcwd(), load_config())
    if not rc:
        log_error(".envrc not found"); return 1
    # Force reload by unsetting our state notion; practically prints an export for current shell.
    os.environ.pop("DIRENV_DIFF", None)
    return prepare_export("bash")

def cmd_log(args):
    if len(args) < 2 or args[0] not in ("--status","--error"):
        log_error("invalid arguments"); return 1
    msg=" ".join(args[1:])
    if args[0] == "--error":
        sys.stderr.write(f"{ERROR_RED}direnv: {msg}{RESET}\n")
    else:
        sys.stderr.write(f"{RESET}direnv: {msg}\n")
    return 0

# dotenv private command
def dotenv_to_env(path, base=None):
    base = dict(base or os.environ)
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    bash=shutil.which("bash") or "/usr/bin/bash"
    dump=tempfile.NamedTemporaryFile(delete=False); dump.close()
    script=f"set -a\nsource {bash_quote(os.path.abspath(path))}\nset +a\nenv -0 > {bash_quote(dump.name)}\n"
    p=subprocess.run([bash,"-c",script], env=base, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.stderr:
        sys.stderr.buffer.write(p.stderr)
    if p.returncode != 0:
        try: os.unlink(dump.name)
        except Exception: pass
        raise RuntimeError(f"exit status {p.returncode}")
    data=open(dump.name,"rb").read(); os.unlink(dump.name)
    env={}
    for item in data.split(b"\0"):
        if item and b"=" in item:
            k,v=item.split(b"=",1); env[k.decode(errors="replace")]=v.decode(errors="replace")
    return env

def cmd_dotenv(args):
    shell=args[0] if args else "bash"
    path=args[1] if len(args)>1 else ".env"
    if not check_shell(shell): return 1
    if not os.path.exists(path):
        log_error(f"open {path}: no such file or directory"); return 1
    base=dict(os.environ)
    try: env=dotenv_to_env(path, base)
    except Exception as e:
        log_error(str(e)); return 1
    changes=env_changes(base, env)
    for k in list(changes):
        if k in INTERNAL_IGNORES or k in CONTROL_VARS: changes.pop(k,None)
    out=render(shell, changes)
    if out: sys.stdout.write(out)
    return 0

def cmd_dump(args):
    shell=args[0] if args and args[0] in ("bash","json","gzenv") else "gzenv"
    filearg=None
    if args:
        if args[0] in ("bash","json","gzenv") and len(args)>1: filearg=args[1]
        elif args[0] not in ("bash","json","gzenv"): filearg=args[0]
    env={k:v for k,v in os.environ.items() if k not in INTERNAL_IGNORES}
    if filearg:
        try:
            env.update(show_dump(open(filearg).read()))
        except Exception: pass
    if shell == "json": print(json.dumps(env, indent=2, sort_keys=True)); return 0
    if shell == "bash": sys.stdout.write(render("bash", env)); return 0
    sys.stdout.write(b64z({"env":env}))
    return 0

def show_dump(s):
    d=unb64z(s.strip())
    if isinstance(d,dict) and "env" in d: return d["env"]
    if isinstance(d,dict): return d
    return {}

def cmd_show_dump(args):
    if not args: log_error("not enough arguments"); return 1
    print(json.dumps(show_dump(args[0]), indent=2, sort_keys=True)); return 0

def cmd_apply_dump(args):
    if not args:
        log_error("not enough arguments"); return 1
    try:
        content=open(args[0]).read()
        env=show_dump(content)
    except Exception as e:
        log_error(str(e)); return 1
    changes=env_changes(dict(os.environ), env)
    sys.stdout.write(render("bash", changes)); return 0

def cmd_watch(args):
    if not args:
        log_error("not enough arguments"); return 1
    shell=args[0]; paths=args[1:]
    if not check_shell(shell): return 1
    obj={"py_watches":1,"files":[]}
    for p in paths:
        try:
            st=os.stat(p); obj["files"].append([os.path.abspath(p),int(st.st_mtime),st.st_size])
        except Exception: obj["files"].append([os.path.abspath(p),0,0])
    sys.stdout.write(render(shell,{"DIRENV_WATCHES":b64z(obj)})); return 0

def cmd_watch_list(args):
    shell=args[0] if args else "bash"
    if not check_shell(shell): return 1
    obj={"py_watches":1,"raw":sys.stdin.read()}
    sys.stdout.write(render(shell,{"DIRENV_WATCHES":b64z(obj)})); return 0

def cmd_watch_print(args):
    null = args and args[0] == "--null"
    d=unb64z(os.environ.get("DIRENV_WATCHES","")) or {}
    files=[x[0] for x in d.get("files",[]) if isinstance(x,list) and x]
    sep="\0" if null else "\n"
    if files: sys.stdout.write(sep.join(files) + sep)
    return 0

def cmd_current(args):
    if not args:
        log_error("not enough arguments"); return 1
    p=os.path.abspath(args[0])
    d=unb64z(os.environ.get("DIRENV_WATCHES","")) or {}
    for x in d.get("files",[]):
        if x and os.path.abspath(x[0]) == p:
            try:
                st=os.stat(p)
                return 0 if int(st.st_mtime)==int(x[1]) and st.st_size==x[2] else 1
            except Exception: return 1
    log_error(f"File \"{p}\" is unknown"); return 1

def cmd_check_required(args):
    if len(args) < 2:
        log_error("not enough arguments"); return 1
    shell=args[0]; paths=args[2:]
    if not check_shell(shell): return 1
    bad=[]
    for p in paths:
        if auth_status(os.path.abspath(p)) != "allowed": bad.append(p)
    if bad:
        for p in bad: log_error(f"{p} is blocked. Run `direnv allow` to approve its content")
        return 1
    return 0

def cmd_fetchurl(args):
    if not args:
        log_error("missing URL argument"); return 1
    url=args[0]; want=args[1] if len(args)>1 else None
    try:
        if url.startswith("file://"):
            data=open(url[7:],"rb").read()
        elif os.path.exists(url):
            data=open(url,"rb").read()
        else:
            req=Request(url, headers={"User-Agent":"direnv"})
            data=urlopen(req, timeout=30).read()
    except Exception as e:
        log_error(str(e)); return 1
    h="sha256-"+base64.b64encode(hashlib.sha256(data).digest()).decode()
    if not want:
        if sys.stdout.isatty():
            print(f"Found hash: {h}\n")
            print("Invoke fetchurl again with the hash as an argument to get the disk location:\n")
            print(f"  direnv fetchurl \"{url}\" \"{h}\"")
        else:
            print(h)
        return 0
    if want != h:
        log_error(f"integrity mismatch: expected {want}, got {h}"); return 1
    name=h.replace('/','_')
    d=os.path.join(cache_dir(),"cas"); os.makedirs(d, exist_ok=True)
    p=os.path.join(d,name)
    if not os.path.exists(p):
        with open(p,"wb") as f: f.write(data)
        os.chmod(p,0o555)
    print(p); return 0

# ---------------- main ----------------
def main(argv):
    if not argv or argv[0] in ("help","--help","-h"):
        show = len(argv)>1 and argv[1] not in ("0","false","")
        return cmd_help(show)
    cmd=argv[0]; args=argv[1:]
    aliases={"permit":"allow","grant":"allow","deny":"block","disallow":"block","revoke":"block","--version":"version","-V":"version"}
    cmd=aliases.get(cmd,cmd)
    try:
        if cmd=="version": return cmd_version(args)
        if cmd=="hook": return cmd_hook(args)
        if cmd=="allow": return cmd_allow(args, False)
        if cmd=="block": return cmd_allow(args, True)
        if cmd=="edit": return cmd_edit(args)
        if cmd=="export": return prepare_export(args[0] if args else "")
        if cmd=="exec": return cmd_exec(args)
        if cmd=="status": return cmd_status(args)
        if cmd=="stdlib": sys.stdout.write(stdlib_text()); return 0
        if cmd=="prune": return cmd_prune()
        if cmd=="reload": return cmd_reload()
        if cmd=="log": return cmd_log(args)
        if cmd=="dotenv": return cmd_dotenv(args)
        if cmd=="dump": return cmd_dump(args)
        if cmd=="show_dump": return cmd_show_dump(args)
        if cmd=="apply_dump": return cmd_apply_dump(args)
        if cmd=="watch": return cmd_watch(args)
        if cmd=="watch-dir":
            if len(args)<2: log_error("not enough arguments"); return 1
            paths=[]
            for root,dirs,files in os.walk(args[1]):
                paths.append(root)
                for f in files: paths.append(os.path.join(root,f))
            return cmd_watch([args[0]]+paths)
        if cmd=="watch-list": return cmd_watch_list(args)
        if cmd=="watch-print": return cmd_watch_print(args)
        if cmd=="current": return cmd_current(args)
        if cmd=="check-required": return cmd_check_required(args)
        if cmd=="fetchurl": return cmd_fetchurl(args)
        log_error(f"command \"{self_path()} {cmd}\" not found"); return 1
    except BrokenPipeError:
        return 0
    except Exception as e:
        log_error(str(e)); return 1

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
